"""Read-only user-visible evidence for a job's immutable camera calibration."""
import json
import os
from pathlib import Path


def render(bundle_path, output, *, runtime=None, video_url=None):
    bundle_path, output = Path(bundle_path), Path(output)
    bundle = json.loads(bundle_path.read_text())
    bundle['runtime_calibration'] = runtime
    bundle['review_video_url'] = video_url
    output.mkdir(parents=True, exist_ok=False)
    for asset in bundle['calibrations']:
        for panel in asset['panels'].values():
            panel['frame']['image_url'] = os.path.relpath(bundle_path.parent/panel['frame']['image_path'], output)
    payload = json.dumps(bundle).replace('<', '\\u003c')
    (output/'index.html').write_text(TEMPLATE.replace('__DATA__', payload))


TEMPLATE='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Camera calibration evidence</title>
<style>body{font:16px/1.5 system-ui;margin:24px;color:#213c43;background:#f4f7f7}section{background:white;border:1px solid #dce6e7;border-radius:8px;padding:18px;margin:15px 0}canvas{width:100%;max-width:650px;display:block}h1{margin-bottom:4px}p{max-width:1000px}pre{white-space:pre-wrap;font-size:12px}button{padding:8px;background:white;border:1px solid #aac5c6;border-radius:5px}table{border-collapse:collapse;font-size:13px}td,th{padding:4px 10px;text-align:left;border-bottom:1px solid #dce6e7}</style>
<h1>Saved source calibration</h1><p>Saved operator calibration. Cyan shows the rink projection. Template placement records visual alignment only, without independent landmark residuals. In point mode, fit marks are green and withheld checks are magenta. Neither method establishes independent physical trajectory accuracy.</p><p id="source"></p><button id="toggle">Hide projection overlay</button><section id="runtime" hidden><h2>Runtime calibration support</h2><p id="coverage"></p><div id="gaps"></div><video id="reviewVideo" controls preload="metadata" style="width:100%;max-width:1000px"></video><p>Gap times identify sampled frames where a mapping was unavailable. Occlusion and camera changes require source review. This video has no inferred geometry overlay.</p></section><div id="records"></div>
<script>const bundle=__DATA__;let overlays=true;document.querySelector('#source').textContent='Source SHA-256: '+bundle.source_sha256;const draws=[];
const runtime=bundle.runtime_calibration;if(runtime){document.querySelector('#runtime').hidden=false;document.querySelector('#coverage').textContent=Object.entries(runtime.camera_coverage).map(([p,c])=>p+': '+c.registered_frames+'/'+c.frames+' sampled frames supported; '+c.unsupported_stone_points+' detections outside available calibration support').join(' · ');const video=document.querySelector('#reviewVideo');video.src=bundle.review_video_url;const gaps=Object.values(runtime.gap_intervals||{}).flat();for(const gap of gaps){const button=document.createElement('button');button.textContent=gap.panel+' · '+gap.start_s.toFixed(2)+'–'+gap.end_s.toFixed(2)+' s · '+gap.sampled_frames+' samples · '+gap.status;button.onclick=()=>{const seek=()=>{video.pause();video.currentTime=gap.start_s};if(video.readyState>=1)seek();else video.addEventListener('loadedmetadata',seek,{once:true});video.scrollIntoView({block:'center'})};document.querySelector('#gaps').append(button)}if(!gaps.length)document.querySelector('#gaps').textContent='No missing camera-pose intervals in this scan. Projection support and physical accuracy remain separate checks.';}
function text(tag,value,parent){const e=document.createElement(tag);e.textContent=value;parent.append(e);return e}
for(const asset of bundle.calibrations){const section=document.createElement('section');document.querySelector('#records').append(section);text('h2','Calibration '+asset.id,section);text('p',asset.valid_interval_s[0].toFixed(2)+'–'+asset.valid_interval_s[1].toFixed(2)+' s · '+asset.reviewer+' ('+asset.operator_kind+') · confirmed source-overlay review; physical accuracy unverified',section);
for(const [name,p] of Object.entries(asset.panels)){text('h3',name+' camera · source '+p.frame.time_s.toFixed(3)+' s / frame '+p.frame.frame_index,section);text('p',p.projection_scope==='operator_template_alignment'?'One regulation-rink template positioned by the operator. Visual alignment only; no independent landmark error measured.':p.projection_scope==='perspective_constrained'?'Perspective constrained by explicitly marked longitudinal lines.':'Local mapping: positions outside the marked image region are unsupported.',section);const c=document.createElement('canvas');c.width=960;c.height=1080;section.append(c);const image=new Image();function draw(){const ctx=c.getContext('2d');ctx.drawImage(image,name==='left'?0:image.naturalWidth/2,0,image.naturalWidth/2,image.naturalHeight,0,0,960,1080);const xy=pt=>[(pt[0]-(name==='right'?.5:0))*1920,pt[1]*1080];if(overlays){ctx.strokeStyle='#00ffff';ctx.lineWidth=2;for(const line of p.overlay_lines_normalized){ctx.beginPath();line.forEach((pt,i)=>ctx[i?'lineTo':'moveTo'](...xy(pt)));ctx.stroke()}}for(const [points,color] of [[p.fit_points,'#21ff7a'],[p.check_points,'#ff6ff5']]){ctx.strokeStyle=color;ctx.fillStyle=color;for(const point of points){const a=xy(point.pixel_normalized);ctx.beginPath();ctx.arc(...a,5,0,2*Math.PI);ctx.stroke();ctx.font='14px system-ui';ctx.fillText((point.landmark_id||point.feature_id),a[0]+7,a[1]-6)}}}draws.push(draw);image.onload=draw;image.src=p.frame.image_url;const table=document.createElement('table');section.append(table);const head=document.createElement('tr');table.append(head);for(const h of ['Landmark','Use','Reprojection px at 1080p','Marking/point residual m'])text('th',h,head);for(const check of p.checks){const row=document.createElement('tr');table.append(row);for(const v of [check.landmark_id,check.use,check.reprojection_error_px_at_1080p.toFixed(2),check.local_error_m.toFixed(4)])text('td',v,row)}}const details=document.createElement('details');section.append(details);text('summary','Policy, provenance and source evidence',details);text('pre',JSON.stringify(asset,null,2),details)}
document.querySelector('#toggle').onclick=()=>{overlays=!overlays;document.querySelector('#toggle').textContent=overlays?'Hide projection overlay':'Show projection overlay';draws.forEach(fn=>fn())};</script></html>'''
